+.avatar-url-label {
+    font-size: 0.8rem;
+    color: #777;
+    margin: 0.5rem 0 0.25rem;
+}
+
+.avatar-url {
+    font-size: 0.75rem;
+    color: #555;
+    word-break: break-all;
+    max-width: 140px;
+    display: block;
+}
+
+.profile-fields {
+    flex: 1;
+}
+
+/* Toggle switches */
+.toggle-group {
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+}
+
+.toggle-row {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 0.75rem 1rem;
+    background: #f8f9fa;
+    border-radius: 8px;
+    cursor: pointer;
+}
+
+.toggle-row span:first-child {
+    font-weight: 500;
+}
+
+.toggle-switch {
+    width: 2.5rem;
+    height: 1.3rem;
+    cursor: pointer;
+}
+
+/* Channel list */
+.channel-list {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.5rem 0.75rem;
+    border-radius: 6px;
+    cursor: pointer;
+}
+
+.channel-item:hover {
+    background: #f0f0f0;
+}
+
+/* Expandable panel */
+.expandable-panel {
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    overflow: hidden;
+}
+
+.panel-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    width: 100%;
+    padding: 1rem 1.25rem;
+    background: #f8f9fa;
+    border: none;
+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+    color: #333;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.expand-icon {
+    font-size: 0.9rem;
+}
+
+.panel-body {
+    padding: 1.25rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+.error-text {
+    color: #c62828;
+    font-size: 0.85rem;
+    margin: 0.5rem 0;
+}
+
+.info-text {
+    color: #666;
+    font-size: 0.85rem;
+    margin-top: 0.75rem;
+}
+
+/* Status indicator */
+.status-indicator {
+    font-size: 0.8rem;
+    padding: 0.2rem 0.6rem;
+    border-radius: 12px;
+    font-weight: 500;
+}
+
+.status-on {
+    background: #c8e6c9;
+    color: #2e7d32;
+}
+
+.status-off {
+    background: #ffcdd2;
+    color: #c62828;
+}
+
+/* Sessions table */
+.sessions-table-wrapper {
+    overflow-x: auto;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    text-align: left;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    color: #555;
+}
+
+.sessions-table tbody tr:hover {
+    background: #f5f5f5;
+}
+
+.current-badge {
+    font-size: 0.75rem;
+    background: #e3f2fd;
+    color: #1565c0;
+    padding: 0.2rem 0.5rem;
+    border-radius: 10px;
+    font-weight: 500;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal-dialog {
+    background: white;
+    border-radius: 12px;
+    padding: 2rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
+}
+
+.modal-dialog h4 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+}
+
+.modal-dialog p {
+    color: #555;
+    margin-bottom: 1.25rem;
+}
+
+/* Radio group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.25rem;
+}
+
+.radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Appearance preview */
+.appearance-preview {
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    padding: 1.5rem;
+    margin-top: 0.5rem;
+    transition: all 0.3s ease;
+}
+
+.appearance-preview.preview-theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+.appearance-preview.preview-theme-dark {
+    background: #1e1e1e;
+    color: #e0e0e0;
+}
+
+.appearance-preview.preview-theme-system {
+    background: #f5f5f5;
+    color: #444;
+}
+
+.appearance-preview.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.appearance-preview.preview-font-medium {
+    font-size: 1rem;
+}
+
+.appearance-preview.preview-font-large {
+    font-size: 1.2rem;
+}
+
+.appearance-preview.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.preview-header {
+    font-weight: 600;
+    font-size: 1.2em;
+    margin-bottom: 0.5rem;
+}
+
+.preview-text {
+    margin-bottom: 0.75rem;
+    opacity: 0.85;
+}
+
+.preview-button {
+    padding: 0.4rem 1rem;
+    border-radius: 4px;
+    border: none;
+    cursor: pointer;
+    font-size: 0.9em;
+}
+
+.preview-theme-light .preview-button {
+    background: #1565c0;
+    color: white;
+}
+
+.preview-theme-dark .preview-button {
+    background: #64b5f6;
+    color: #1e1e1e;
+}
+
+.preview-theme-system .preview-button {
+    background: #455a64;
+    color: white;
+}
+
+/* Loading */
+.loading-spinner {
+    text-align: center;
+    padding: 3rem;
+    color: #888;
+    font-size: 1.1rem;
+}
+

